import { test, beforeEach, afterEach } from 'node:test';
import { request as httpRequest } from 'node:http';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { Readable } from 'node:stream';
import { readdir, access } from 'node:fs/promises';
import { testServer } from './helpers.js';
let server, owner, guest, org, project, issue, cookie, guestCookie, guestId;
beforeEach(async () => {
  server = await testServer({ maxUploadBytes: 128 * 1024 }); owner = server.agent(); guest = server.agent();
  cookie = (await owner('POST', '/auth/signup', { name: 'Files', email: 'owner@files.test', password: 'correct-horse-123' })).cookie;
  const created = await guest('POST', '/auth/signup', { name: 'Guest', email: 'guest@files.test', password: 'correct-horse-123' }); guestCookie = created.cookie; guestId = created.data.user.id;
  org = (await owner('POST', '/orgs', { name: 'File Org' })).data.organization;
  await owner('POST', '/orgs/' + org.id + '/members', { userId: guestId, role: 'guest' });
  project = (await owner('POST', '/orgs/' + org.id + '/projects', { key: 'FL', name: 'Files' })).data.project;
  issue = (await owner('POST', '/projects/' + project.id + '/issues', { title: 'Attachment issue' })).data.issue;
});
afterEach(async () => { await server.close(); });
async function upload(bytes, options = {}) {
  const response = await fetch(server.url + '/api/v1/issues/' + issue.id + '/attachments?name=' + encodeURIComponent(options.name ?? 'evidence.bin'), {
    method: 'POST', headers: { cookie: options.cookie ?? cookie, 'X-Crew-Request': '1', 'Content-Type': 'application/octet-stream', ...options.headers }, body: bytes, ...(options.stream ? { duplex: 'half' } : {})
  });
  return { status: response.status, data: await response.json() };
}
test('streamed attachment stores SHA-256 size and exact binary bytes', async () => {
  const bytes = Buffer.from([0, 255, 127, 10, 13, 65, 0, 90]);
  const digest = createHash('sha256').update(bytes).digest('hex');
  const result = await upload(Readable.from([bytes.subarray(0, 3), bytes.subarray(3)]), { stream: true, headers: { 'X-Content-SHA256': digest } });
  assert.equal(result.status, 201, JSON.stringify(result.data)); const attachment = result.data.attachment;
  assert.equal(attachment.size, bytes.length); assert.equal(attachment.sha256, digest);
  const response = await fetch(server.url + attachment.downloadUrl, { headers: { cookie } });
  assert.equal(response.headers.get('x-content-sha256'), digest); assert.equal(response.headers.get('content-length'), String(bytes.length));
  assert.deepEqual(Buffer.from(await response.arrayBuffer()), bytes);
});
test('known oversized upload returns stable 413 and creates no metadata', async () => {
  const result = await upload(Buffer.alloc(128 * 1024 + 1));
  assert.equal(result.status, 413); assert.equal(result.data.error.code, 'TOO_LARGE');
  assert.equal((await owner('GET', '/issues/' + issue.id + '/attachments')).data.items.length, 0);
});
test('chunked oversized upload also returns 413 and removes temporary bytes', async () => {
  const result = await upload(Readable.from([Buffer.alloc(65536), Buffer.alloc(65536), Buffer.from('x')]), { stream: true });
  assert.equal(result.status, 413); assert.deepEqual(await readdir(server.ctx.config.dataDir + '/attachments'), []);
});
test('hash mismatch and malformed expected digest leave no blob or metadata', async () => {
  assert.equal((await upload(Buffer.from('bytes'), { headers: { 'X-Content-SHA256': '0'.repeat(64) } })).status, 422);
  assert.equal((await upload(Buffer.from('bytes'), { headers: { 'X-Content-SHA256': 'wrong' } })).status, 422);
  assert.deepEqual(await readdir(server.ctx.config.dataDir + '/attachments'), []);
});
test('attachment file names reject traversal and control separators', async () => {
  assert.equal((await upload(Buffer.from('bytes'), { name: '../private' })).status, 422);
  assert.equal((await upload(Buffer.from('bytes'), { name: 'directory/file' })).status, 422);
});
test('zero-byte attachment preserves the empty hash and exact empty download', async () => {
  const result = await upload(Buffer.alloc(0)); assert.equal(result.status, 201);
  assert.equal(result.data.attachment.sha256, createHash('sha256').digest('hex'));
  const response = await fetch(server.url + result.data.attachment.downloadUrl, { headers: { cookie } });
  assert.equal((await response.arrayBuffer()).byteLength, 0);
});
test('guest must have project access to list or download and cannot upload', async () => {
  const attachment = (await upload(Buffer.from('private'))).data.attachment;
  assert.equal((await guest('GET', '/issues/' + issue.id + '/attachments')).status, 403);
  assert.equal((await fetch(server.url + attachment.downloadUrl, { headers: { cookie: guestCookie } })).status, 403);
  await owner('POST', '/projects/' + project.id + '/guests', { userId: guestId });
  assert.equal((await guest('GET', '/issues/' + issue.id + '/attachments')).data.items[0].id, attachment.id);
  assert.equal((await upload(Buffer.from('no'), { cookie: guestCookie })).status, 403);
});
test('deleting attachment removes metadata and bytes and emits complete events', async () => {
  const events = []; server.ctx.bus.subscribe(event => events.push(event));
  const attachment = (await upload(Buffer.from('delete'))).data.attachment;
  assert.equal((await owner('DELETE', '/attachments/' + attachment.id)).status, 200);
  assert.equal((await owner('GET', '/attachments/' + attachment.id)).status, 404);
  await assert.rejects(() => access(server.ctx.config.dataDir + '/attachments/' + attachment.id + '.blob'));
  const event = events.find(event => event.entityType === 'attachment' && event.action === 'deleted');
  assert.equal(event.before.sha256, attachment.sha256); assert.equal(event.after, null); assert.equal(event.projectId, project.id);
});
test('issue and project deletion reclaim their attachment blobs', async () => {
  await upload(Buffer.from('delete with issue'));
  await owner('DELETE', '/issues/' + issue.id);
  assert.deepEqual(await readdir(server.ctx.config.dataDir + '/attachments'), []);
  assert.equal(server.ctx.db.prepare('SELECT count(*) AS n FROM attachments').get().n, 0);
});
async function waitForFileState(predicate, message) {
  const until = Date.now() + 2000;
  while (Date.now() < until) {
    let names = []; try { names = await readdir(server.ctx.config.dataDir + '/attachments'); } catch (error) { if (error.code !== 'ENOENT') throw error; }
    if (predicate(names)) return;
    await new Promise(resolve => setTimeout(resolve, 5));
  }
  throw new Error(message);
}
test('membership revoked during streamed upload is rechecked before metadata publication', async () => {
  await owner('PATCH', '/orgs/' + org.id + '/members/' + guestId, { role: 'member' });
  let incoming;
  const result = new Promise((resolve, reject) => {
    incoming = httpRequest(server.url + '/api/v1/issues/' + issue.id + '/attachments?name=revoked.bin', {
      method: 'POST', headers: { cookie: guestCookie, 'X-Crew-Request': '1', 'Content-Type': 'application/octet-stream' }
    }, response => {
      let body = ''; response.setEncoding('utf8'); response.on('data', chunk => { body += chunk; });
      response.on('end', () => resolve({ status: response.statusCode, data: JSON.parse(body) }));
    });
    incoming.setTimeout(2500, () => incoming.destroy(new Error('Upload test deadline exceeded')));
    incoming.on('error', reject); incoming.write(Buffer.from('first chunk'));
  });
  await waitForFileState(names => names.some(name => name.endsWith('.upload')), 'Upload did not open its private temporary file');
  await owner('PATCH', '/orgs/' + org.id + '/members/' + guestId, { role: 'guest' });
  incoming.end(Buffer.from('last chunk'));
  assert.equal((await result).status, 403);
  assert.equal((await owner('GET', '/issues/' + issue.id + '/attachments')).data.items.length, 0);
  assert.deepEqual(await readdir(server.ctx.config.dataDir + '/attachments'), []);
});
test('project deletion removes child issues and their retained attachment metadata and bytes', async () => {
  const result = await upload(Buffer.from('project bytes')); assert.equal(result.status, 201);
  const removed = await owner('DELETE', '/projects/' + project.id); assert.equal(removed.status, 200, JSON.stringify(removed.data));
  assert.deepEqual(await readdir(server.ctx.config.dataDir + '/attachments'), []);
  assert.equal(server.ctx.db.prepare('SELECT count(*) AS n FROM attachments').get().n, 0);
});
test('archive rejects new attachment writes and attachments paginate stably', async () => {
  await upload(Buffer.from('one'), { name: 'one.bin' }); await upload(Buffer.from('two'), { name: 'two.bin' });
  const page = (await owner('GET', '/issues/' + issue.id + '/attachments?limit=1')).data;
  assert(page.nextCursor); assert.equal((await owner('GET', '/issues/' + issue.id + '/attachments?limit=1&cursor=' + page.nextCursor)).data.items.length, 1);
  await owner('PATCH', '/projects/' + project.id, { archived: true }); assert.equal((await upload(Buffer.from('no'))).status, 409);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { testServer } from './helpers.js';
import { seed } from '../../../scripts/checks/seed.mjs';
test('demo seed is idempotent and creates usable owner member guest project work', async () => {
  const server = await testServer();
  try {
    await seed(server.ctx);
    const counts = () => Object.fromEntries(['users', 'organizations', 'teams', 'projects', 'issues', 'project_guests'].map(table => [table, server.ctx.db.prepare('SELECT COUNT(*) AS n FROM ' + table).get().n]));
    const before = counts(); await seed(server.ctx); assert.deepEqual(counts(), before);
    assert.equal(before.users, 3); assert.equal(before.projects, 1); assert.equal(before.issues, 3);
    const guest = server.agent();
    assert.equal((await guest('POST', '/auth/login', { email: 'guest@crew.demo', password: 'crew-demo-password-2026' })).status, 200);
    assert.equal((await guest('GET', '/projects')).data.items[0].key, 'DEMO');
  } finally { await server.close(); }
});
